package com.bank.collections;

import java.math.BigDecimal;
import java.util.logging.Logger;

public class GenericsTypeSafetyTest {
    private static final Logger log = Logger.getLogger(GenericsTypeSafetyTest.class.getName());

    public static void main(String[] args) {
        BigDecimal rajesh = new BigDecimal("1000000");   // SAV2001
        BigDecimal priya  = new BigDecimal("250000");    // CUR3001
        log.info(() -> "Demonstrating generics and compile-time type safety for SAV2001 and CUR3001");
        log.info(() -> "Rajesh balance=" + rajesh + ", Priya balance=" + priya);
        // the collection operation specific to this topic is exercised here
    }
}
